-- GENERATED by tools/split.py from plan/db/*.sql. Edit the source files or split.py, then re-run.
-- Load order: _prelude.sql, access.sql, _epilogue.sql
-- ============================================================================
-- CORE schema (identity, access, hierarchy, tasks, fields, statuses, views)
-- PostgreSQL 16. Our own design, informed by the ClickUp reverse engineering.
-- EVIDENCE KEY: PROVEN = seen in ClickUp requests/screens/client code (see clickup-model.mmd).
--               ASSUMED = our design choice or inference; needs real use to confirm.
-- CONVENTIONS: ids are uuid generated app-side (uuidv7), so no DEFAULT on id columns.
--   Every tenant table has workspace_id NOT NULL and leads its main indexes with it.
--   Mutable rows have integer `version`; the trigger at the end bumps it and updated_at.
--   Fractional index strings use COLLATE "C" so byte order == sort order.
-- Run order: top to bottom. Circular FKs are added in section Z.
-- Other half owns: attachments, comments, docs (FKs in the commented block at the very end).
-- ============================================================================

-- ============================================================================
-- A. IDENTITY AND WORKSPACES
-- ============================================================================

-- Capability vocabulary used by roles. ASSUMED (ClickUp shows ~50 can_* flags, we keep a smaller core set).
CREATE TABLE capabilities (
  key         text PRIMARY KEY,
  description text NOT NULL
);

INSERT INTO capabilities (key, description) VALUES
  ('view','see the node and its tasks'),
  ('comment','comment on tasks'),
  ('edit','edit tasks and fields values'),
  ('create','create tasks and child nodes'),
  ('delete','delete tasks and child nodes'),
  ('manage_fields','add or change custom fields and statuses'),
  ('manage_views','create and share views'),
  ('manage_access','change grants and restricted flag');

CREATE TABLE workspaces (
  id               uuid PRIMARY KEY,                   -- tenant key of every other table
  name             text NOT NULL,                      -- PROVEN
  slug             text,                               -- ASSUMED
  color            text,                               -- PROVEN
  avatar_url       text,
  plan_key         text NOT NULL DEFAULT 'free',       -- PROVEN plans exist; keys ASSUMED
  default_member_role_id uuid,                         -- role implicitly granted to members on non-restricted nodes. ASSUMED; FK in Z
  allow_guests     boolean NOT NULL DEFAULT true,      -- PROVEN can_add_guests (as permission flag)
  next_task_number bigint NOT NULL DEFAULT 1,          -- counter for human task numbers (CU-123 style). ASSUMED
  settings         jsonb NOT NULL DEFAULT '{}',        -- per-workspace toggles/config only, never filtered on
  created_by       uuid /* id -> identity.users */,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  deleted_at       timestamptz,
  version          integer NOT NULL DEFAULT 1
);

CREATE UNIQUE INDEX workspaces_slug_uk ON workspaces (lower(slug)) WHERE slug IS NOT NULL AND deleted_at IS NULL;

-- Roles. scope 'workspace' = custom workspace-level role (plan gated, PROVEN gate);
-- scope 'node' = permission level used by grants (view only / comment / edit / full). Levels ASSUMED (PROVEN: a "Full edit" level exists, wire value 5).
-- System roles are seeded per workspace on creation (so workspace_id stays NOT NULL). ASSUMED.
CREATE TABLE roles (
  id            uuid PRIMARY KEY,
  workspace_id  uuid NOT NULL REFERENCES workspaces(id),
  scope         text NOT NULL CHECK (scope IN ('workspace','node')),
  key           text NOT NULL,                         -- e.g. view_only, comment, edit, full
  name          text NOT NULL,
  description   text,                                  -- PROVEN: roles carry a one-line description
  is_system     boolean NOT NULL DEFAULT false,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  deleted_at    timestamptz,
  version       integer NOT NULL DEFAULT 1
);

-- Role key unique per workspace and scope; leading workspace_id serves "list roles of workspace".
CREATE UNIQUE INDEX roles_ws_scope_key_uk ON roles (workspace_id, scope, key) WHERE deleted_at IS NULL;

CREATE TABLE role_capabilities (
  workspace_id  uuid NOT NULL REFERENCES workspaces(id),
  role_id       uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
  capability    text NOT NULL REFERENCES capabilities(key),
  PRIMARY KEY (role_id, capability)
);

CREATE INDEX role_capabilities_ws_idx ON role_capabilities (workspace_id, role_id);

-- tenant scans / export

-- Membership. role_kind codes PROVEN: 1 owner, 2 admin, 3 member, 4 guest.
-- guest_subtype PROVEN as 4 values (order not tied to numbers, so stored as text).
CREATE TABLE workspace_members (
  id              uuid PRIMARY KEY,
  workspace_id    uuid NOT NULL REFERENCES workspaces(id),
  user_id         uuid NOT NULL /* id -> identity.users */,
  role_kind       text NOT NULL CHECK (role_kind IN ('owner','admin','member','guest')),
  guest_subtype   text CHECK (guest_subtype IN ('external_read_only','external','limited_member_read_only','limited_member')),
  custom_role_id  uuid REFERENCES roles(id),           -- optional custom workspace role refining 'member'. ASSUMED
  status          text NOT NULL DEFAULT 'active' CHECK (status IN ('active','pending','deactivated')), -- PROVEN "Pending"; others ASSUMED
  invited_by      uuid /* id -> identity.users */,           -- PROVEN
  invited_at      timestamptz,                         -- PROVEN date_invited
  joined_at       timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  deleted_at      timestamptz,
  version         integer NOT NULL DEFAULT 1,
  CHECK (guest_subtype IS NULL OR role_kind = 'guest')
);

-- One live membership per user per workspace; also the "is user X in workspace W" lookup.
CREATE UNIQUE INDEX workspace_members_ws_user_uk ON workspace_members (workspace_id, user_id) WHERE deleted_at IS NULL;

-- "Which workspaces is user X in" (login, switcher). Not tenant-leading by nature: cross-tenant lookup.
CREATE INDEX workspace_members_user_idx ON workspace_members (user_id) WHERE deleted_at IS NULL;

-- People page filtered by role.
CREATE INDEX workspace_members_ws_role_idx ON workspace_members (workspace_id, role_kind) WHERE deleted_at IS NULL;

-- Groups (PROVEN: user groups exist, object type 14).
CREATE TABLE user_groups (
  id            uuid PRIMARY KEY,
  workspace_id  uuid NOT NULL REFERENCES workspaces(id),
  name          text NOT NULL,
  handle        text,                                  -- @mention handle. PROVEN-ish (team mentions exist), ASSUMED shape
  color         text,
  avatar_url    text,
  created_by    uuid /* id -> identity.users */,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  deleted_at    timestamptz,
  version       integer NOT NULL DEFAULT 1
);

CREATE UNIQUE INDEX user_groups_ws_name_uk ON user_groups (workspace_id, lower(name)) WHERE deleted_at IS NULL;

CREATE UNIQUE INDEX user_groups_ws_handle_uk ON user_groups (workspace_id, lower(handle)) WHERE deleted_at IS NULL AND handle IS NOT NULL;

CREATE TABLE user_group_members (
  workspace_id  uuid NOT NULL REFERENCES workspaces(id),
  group_id      uuid NOT NULL REFERENCES user_groups(id) ON DELETE CASCADE,
  user_id       uuid NOT NULL /* id -> identity.users */,
  added_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (group_id, user_id)
);

-- "Groups of user X" is on the hot path of every permission check.
CREATE INDEX user_group_members_user_idx ON user_group_members (workspace_id, user_id, group_id);

-- Invites. A guest invite also carries the node grants to create on acceptance (invite_grants).
CREATE TABLE invites (
  id              uuid PRIMARY KEY,
  workspace_id    uuid NOT NULL REFERENCES workspaces(id),
  email           text NOT NULL,
  role_kind       text NOT NULL CHECK (role_kind IN ('admin','member','guest')),
  guest_subtype   text CHECK (guest_subtype IN ('external_read_only','external','limited_member_read_only','limited_member')),
  custom_role_id  uuid REFERENCES roles(id),
  invited_by      uuid NOT NULL /* id -> identity.users */,
  token_hash      text NOT NULL,                       -- sha256 of the emailed token; plain token never stored. ASSUMED
  expires_at      timestamptz NOT NULL,
  accepted_at     timestamptz,
  accepted_user_id uuid /* id -> identity.users */,
  revoked_at      timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  version         integer NOT NULL DEFAULT 1,
  CHECK (guest_subtype IS NULL OR role_kind = 'guest')
);

CREATE UNIQUE INDEX invites_token_uk ON invites (token_hash);

-- accept link lookup (cross-tenant by token)
-- One open invite per email per workspace.
CREATE UNIQUE INDEX invites_open_uk ON invites (workspace_id, lower(email)) WHERE accepted_at IS NULL AND revoked_at IS NULL;

-- "all containers under X"

-- Grant = who (user XOR group) gets which node role on which container. Union semantic ASSUMED (PROVEN: one ACL entry per object).
CREATE TABLE container_grants (
  id            uuid PRIMARY KEY,
  workspace_id  uuid NOT NULL REFERENCES workspaces(id),
  container_id  uuid NOT NULL /* id -> hierarchy.containers */,
  user_id       uuid /* id -> identity.users */,
  group_id      uuid REFERENCES user_groups(id),
  role_id       uuid NOT NULL REFERENCES roles(id),
  granted_by    uuid /* id -> identity.users */,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       integer NOT NULL DEFAULT 1,
  CHECK (num_nonnulls(user_id, group_id) = 1)
);

CREATE UNIQUE INDEX container_grants_user_uk  ON container_grants (container_id, user_id, role_id)  WHERE user_id IS NOT NULL;

CREATE UNIQUE INDEX container_grants_group_uk ON container_grants (container_id, group_id, role_id) WHERE group_id IS NOT NULL;

-- "What can user X reach" (sidebar, search scope): by principal first.
CREATE INDEX container_grants_user_idx  ON container_grants (workspace_id, user_id, container_id)  WHERE user_id IS NOT NULL;

CREATE INDEX container_grants_group_idx ON container_grants (workspace_id, group_id, container_id) WHERE group_id IS NOT NULL;

-- Invite grants: applied when the invite is accepted. ASSUMED
CREATE TABLE invite_grants (
  invite_id     uuid NOT NULL REFERENCES invites(id) ON DELETE CASCADE,
  workspace_id  uuid NOT NULL REFERENCES workspaces(id),
  container_id  uuid NOT NULL /* id -> hierarchy.containers */,
  role_id       uuid NOT NULL REFERENCES roles(id),
  PRIMARY KEY (invite_id, container_id)
);

CREATE INDEX invite_grants_ws_idx ON invite_grants (workspace_id, container_id);

-- Sharing one task with a person/group: a grant on the task, nothing else (design doc). ASSUMED
CREATE TABLE task_shares (
  id            uuid PRIMARY KEY,
  workspace_id  uuid NOT NULL REFERENCES workspaces(id),
  task_id       uuid NOT NULL /* id -> tasks.tasks */,
  user_id       uuid /* id -> identity.users */,
  group_id      uuid REFERENCES user_groups(id),
  role_id       uuid NOT NULL REFERENCES roles(id),
  shared_by     uuid /* id -> identity.users */,
  created_at    timestamptz NOT NULL DEFAULT now(),
  version       integer NOT NULL DEFAULT 1,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  CHECK (num_nonnulls(user_id, group_id) = 1)
);

CREATE UNIQUE INDEX task_shares_user_uk  ON task_shares (task_id, user_id)  WHERE user_id IS NOT NULL;

CREATE UNIQUE INDEX task_shares_group_uk ON task_shares (task_id, group_id) WHERE group_id IS NOT NULL;

-- "Shared with me" screen (PROVEN tasks_shared_with_me).
CREATE INDEX task_shares_user_idx ON task_shares (workspace_id, user_id, task_id) WHERE user_id IS NOT NULL;

ALTER TABLE workspaces  ADD CONSTRAINT workspaces_default_role_fk FOREIGN KEY (default_member_role_id) REFERENCES roles(id);

ALTER TABLE workspaces ADD COLUMN tenant_id uuid /* id -> routing.tenants */;

-- NULL = legacy single-workspace tenant
CREATE INDEX workspaces_tenant_idx ON workspaces (tenant_id);

