-- core-schema.sql only had 8 node-level capabilities. The FRD permission matrix (12.2) needs workspace-level ones too,
-- and "own or assigned only" for Limited Member. ASSUMED design. Default role contents below are PROPOSED, a company edits them.
ALTER TABLE capabilities ADD COLUMN scope text NOT NULL DEFAULT 'node' CHECK (scope IN ('workspace','node'));

ALTER TABLE role_capabilities ADD COLUMN scope_limit text NOT NULL DEFAULT 'all' CHECK (scope_limit IN ('all','own'));

