-- NOTE: capabilities view_costs, manage_budgets, approve_expenses, use_ai, manage_ai_settings are inserted by enterprise-delta.sql. Call seed_default_roles only after both files ran.
-- Default role templates. Called when a workspace is created. A company can rename, delete or change any of them
-- (is_system stays false for these on purpose: nothing is hard-wired except that one owner must exist).
CREATE OR REPLACE FUNCTION seed_default_roles(p_ws uuid) RETURNS void LANGUAGE plpgsql AS $$
DECLARE
  r record;
  rid uuid;
  def jsonb := '[
   {"key":"boss_admin","name":"Boss admin","scope":"workspace","desc":"Full control including billing and ownership transfer",
    "caps":"ALL"},
   {"key":"super_admin","name":"Super admin","scope":"workspace","desc":"Everything except billing and ownership transfer",
    "caps":"ALL-manage_billing-transfer_ownership"},
   {"key":"admin","name":"Admin","scope":"workspace","desc":"Users, spaces, automations, templates, integrations, audit",
    "caps":"view,comment,edit,create,delete,manage_fields,manage_views,manage_access,create_container,track_time,manage_automations,manage_forms_templates,approve,export_data,view_activity,share_externally,manage_dashboards,manage_users,create_space,view_audit,manage_integrations,manage_api_tokens,manage_workspace_settings"},
   {"key":"pm","name":"Project manager","scope":"node","desc":"Runs a project: statuses, fields, automations, members",
    "caps":"view,comment,edit,create,delete,manage_fields,manage_views,manage_access,create_container,track_time,manage_automations,manage_forms_templates,approve,export_data,view_activity,share_externally,manage_dashboards,view_costs,manage_budgets,approve_expenses,use_ai"},
   {"key":"manager","name":"Manager","scope":"node","desc":"Leads a space or team. Same permissions as Project manager until the company changes them",
    "caps":"view,comment,edit,create,delete,manage_fields,manage_views,manage_access,create_container,track_time,manage_automations,manage_forms_templates,approve,export_data,view_activity,share_externally,manage_dashboards,view_costs,manage_budgets,approve_expenses,use_ai"},
   {"key":"associate","name":"Associate","scope":"node","desc":"Creates and edits work, comments, tracks time",
    "caps":"view,comment,edit,create,track_time,approve,manage_views,use_ai"},
   {"key":"limited_member","name":"Limited member","scope":"node","desc":"Works only on items they created or are assigned to",
    "caps":"view:own,comment:own,edit:own,create:own,track_time:own"},
   {"key":"viewer","name":"Viewer","scope":"node","desc":"Read and comment","caps":"view,comment"},
   {"key":"guest","name":"Guest","scope":"node","desc":"External. Access only to what is explicitly shared","caps":"view,comment"}
  ]';
  item jsonb;
  c text;
  cap text;
  lim text;
BEGIN
  FOR item IN SELECT * FROM jsonb_array_elements(def) LOOP
    rid := gen_random_uuid();
    INSERT INTO roles (id, workspace_id, scope, key, name, description, is_system)
    VALUES (rid, p_ws, item->>'scope', item->>'key', item->>'name', item->>'desc', false);
    c := item->>'caps';
    IF c LIKE 'ALL%' THEN
      FOR cap IN SELECT key FROM capabilities WHERE scope IN ('workspace','node') LOOP
        IF position('-' || cap IN c) = 0 THEN
          INSERT INTO role_capabilities (workspace_id, role_id, capability) VALUES (p_ws, rid, cap);
        END IF;
      END LOOP;
    ELSE
      FOREACH cap IN ARRAY string_to_array(c, ',') LOOP
        lim := CASE WHEN cap LIKE '%:own' THEN 'own' ELSE 'all' END;
        INSERT INTO role_capabilities (workspace_id, role_id, capability, scope_limit)
        VALUES (p_ws, rid, split_part(cap, ':', 1), lim);
      END LOOP;
    END IF;
  END LOOP;
  -- implicit role for plain members on non-restricted nodes
  UPDATE workspaces SET default_member_role_id = (SELECT id FROM roles WHERE workspace_id = p_ws AND key = 'associate')
   WHERE id = p_ws;
END $$;

